        var_dump($client);
        echo print_r($client, true);
        echo var_export($client, true);
        echo json_encode($client);
        echo json_encode((array) $client, \JSON_PARTIAL_OUTPUT_ON_ERROR);
        echo print_r($client->companies, true);
        var_dump($client->chat);
