        self::assertNotSame('', $dump);
        self::assertStringNotContainsString(self::API_KEY, $dump);
        self::assertStringNotContainsString(self::WEBHOOK, $dump);
        self::assertStringNotContainsString('SECRETKEY', $dump);
        self::assertStringContainsString('[redacted]', $dump);
    }

