    public function testAnyPsr18ClientCanBeInjected(): void
    {
        $psr18 = new class () implements ClientInterface {
            /** @var list<RequestInterface> */
            public array $requests = [];
            /** @var list<ResponseInterface|ClientExceptionInterface> */
            public array $script = [];

            public function sendRequest(RequestInterface $request): ResponseInterface
            {
                $this->requests[] = $request;
                $next = array_shift($this->script);
                if ($next instanceof ClientExceptionInterface) {
                    throw $next;
                }
                if ($next === null) {
                    throw new \LogicException('nothing scripted');
                }

                return $next;
            }
        };
        $network = new class ('Could not resolve host: api.tungo.kz') extends \RuntimeException implements \Psr\Http\Client\NetworkExceptionInterface {
            public function getRequest(): RequestInterface
            {
                return (new Psr17Factory())->createRequest('GET', 'http://x');
            }
        };
        $timeout = new class ('Operation timed out after 1000 ms') extends \RuntimeException implements ClientExceptionInterface {
        };
        $client = new TungoClient(apiKey: self::API_KEY, baseUrl: 'http://psr18.test', httpClient: $psr18, retryBaseDelay: 0.01);

        $psr18->script = [$network, new Response(200, [], self::json(self::sample('companies.list')))];
        self::assertNotEmpty($client->companies->list()->data, 'a network exception of a GET is retried');
        self::assertCount(2, $psr18->requests);
        self::assertSame('http://psr18.test/v1/companies', (string) $psr18->requests[0]->getUri());
        self::assertSame(self::API_KEY, $psr18->requests[0]->getHeaderLine('x-api-key'));

        $psr18->script = [$network, $network, $network];
        try {
            $client->companies->list();
            self::fail('a PSR-18 network exception must raise, never look like an empty list');
        } catch (ConnectionError $e) {
            // The cause is a summary of the client's exception: the exception itself holds the request, and with it the key.
            $cause = $e->getPrevious();
            self::assertNotNull($cause);
            self::assertNotInstanceOf(ClientExceptionInterface::class, $cause);
            self::assertStringContainsString('Could not resolve host', $cause->getMessage());
        }

        $psr18->script = [$timeout, $timeout, $timeout];
        try {
            $client->companies->list();
            self::fail('must raise');
        } catch (TimeoutError) {
            $this->addToAssertionCount(1);
        }

        $psr18->script = [new Response(200, ['Content-Type' => 'text/html'], '<html></html>')];
        try {
            $client->companies->list();
            self::fail('must raise');
        } catch (DecodeError $e) {
            self::assertSame(200, $e->status);
        }

        $psr18->script = [new Response(404, [], self::errorBody('not_found_error'))];
        $this->expectException(NotFoundError::class);
        $client->companies->list();
    }

